40	/****************************************************************************
41	 * LVGL 异步回调（在 LVGL 线程中执行）
42	 ****************************************************************************/
43	
44	static void popup_async_cb(void *data)
45	{
46	  popup_data_t *popup_data = (popup_data_t *)data;
47	  if (!popup_data) return;
48	
49	  lv_obj_t *scr = lv_screen_active();
50	  if (!scr) {
51	    free(popup_data);
52	    return;
53	  }
54	
55	  /* 创建全屏遮罩 */
56	
57	  lv_obj_t *overlay = lv_obj_create(scr);
58	  lv_obj_set_size(overlay, 390, 450);
59	  lv_obj_set_style_bg_color(overlay, lv_color_hex(0x000000), 0);
60	  lv_obj_set_style_bg_opa(overlay, LV_OPA_80, 0);
61	  lv_obj_set_style_border_width(overlay, 0, 0);
62	  lv_obj_set_style_radius(overlay, 0, 0);
63	  lv_obj_remove_flag(overlay, LV_OBJ_FLAG_SCROLLABLE);
64	  lv_obj_align(overlay, LV_ALIGN_TOP_LEFT, 0, 0);
65	
66	  /* Flex 布局 */
67	
68	  lv_obj_set_flex_flow(overlay, LV_FLEX_FLOW_COLUMN);
69	  lv_obj_set_flex_align(overlay, LV_FLEX_ALIGN_CENTER,
70	                        LV_FLEX_ALIGN_CENTER,
71	                        LV_FLEX_ALIGN_CENTER);
72	  lv_obj_set_style_pad_row(overlay, 16, 0);
73	
74	  /* 标题 */
75	
76	  lv_obj_t *title = lv_label_create(overlay);
77	  lv_label_set_text(title, popup_data->title);
78	  lv_obj_set_style_text_color(title, lv_color_hex(0xFFFFFF), 0);
79	
80	  /* 内容 */
81	
82	  lv_obj_t *content = lv_label_create(overlay);
83	  lv_label_set_text(content, popup_data->content);
84	  lv_obj_set_style_text_color(content, lv_color_hex(0xAAAAAA), 0);
85	
86	  /* 关闭按钮 */
87	
88	  lv_obj_t *btn = lv_btn_create(overlay);
89	  lv_obj_set_size(btn, 200, 44);
90	  lv_obj_set_style_bg_color(btn, lv_color_hex(0x00E676), 0);
91	  lv_obj_set_style_bg_opa(btn, LV_OPA_COVER, 0);
92	  lv_obj_set_style_radius(btn, 8, 0);
93	
94	  lv_obj_t *btn_label = lv_label_create(btn);
95	  lv_label_set_text(btn_label, "OK");
96	  lv_obj_set_style_text_color(btn_label, lv_color_hex(0x000000), 0);
97	  lv_obj_center(btn_label);
98	
99	  /* 存储 overlay 指针用于关闭回调 */
100	
101	  lv_obj_set_user_data(btn, overlay);
102	
103	  /* 注册关闭回调 */
104	
105	  lv_obj_add_event_cb(btn, popup_btn_close_cb, LV_EVENT_CLICKED, NULL);
106	  lv_obj_add_event_cb(overlay, popup_overlay_close_cb, LV_EVENT_CLICKED, NULL);
107	
108	  printf("[popup] Displayed: %s\n", popup_data->title);
109	  free(popup_data);
110	}
