112	/****************************************************************************
113	 * 显示弹窗
114	 ****************************************************************************/
115	
116	static int show_popup(const char *title, const char *content)
117	{
118	  /* 分配弹窗数据 */
119	
120	  popup_data_t *popup_data = malloc(sizeof(popup_data_t));
121	  if (!popup_data) {
122	    printf("[popup] Error: Memory allocation failed\n");
123	    return -1;
124	  }
125	
126	  /* 复制标题和内容 */
127	
128	  strncpy(popup_data->title, title, sizeof(popup_data->title) - 1);
129	  popup_data->title[sizeof(popup_data->title) - 1] = '\0';
130	  strncpy(popup_data->content, content, sizeof(popup_data->content) - 1);
131	  popup_data->content[sizeof(popup_data->content) - 1] = '\0';
132	
133	  /* 在 LVGL 线程中安全地创建弹窗 */
134	
135	  lv_result_t res = lv_async_call(popup_async_cb, popup_data);
136	  if (res != LV_RESULT_OK) {
137	    free(popup_data);
138	    printf("[popup] Error: lv_async_call failed\n");
139	    return -1;
140	  }
141	
142	  printf("[popup] Scheduled: %s\n", title);
143	  return 0;
144	}
