28	static void btn_confirm_cb(lv_event_t *e)
29	{
30	  struct popup_ctx *ctx = (struct popup_ctx *)lv_event_get_user_data(e);
31	  if (ctx->cb)
32	    ctx->cb(ctx->user_data);
33	  popup_close(ctx->popup);
