51	                       const char *content, const char *btn_text,
52	                       popup_cb_t cb, void *user_data)
53	{
54	  struct popup_ctx *ctx = lv_malloc(sizeof(struct popup_ctx));
55	  if (!ctx) return NULL;
56	  ctx->cb       = cb;
57	  ctx->user_data = user_data;
58	
59	  /* 全屏半透明背景（简化版，无 card 嵌套） */
60	
61	  lv_obj_t *overlay = lv_obj_create(parent);
62	  lv_obj_set_size(overlay, SCREEN_WIDTH, SCREEN_HEIGHT);
63	  lv_obj_set_style_bg_color(overlay, lv_color_hex(0x000000), 0);
64	  lv_obj_set_style_bg_opa(overlay, LV_OPA_80, 0);
65	  lv_obj_set_style_border_width(overlay, 0, 0);
66	  lv_obj_set_style_radius(overlay, 0, 0);
67	  lv_obj_remove_flag(overlay, LV_OBJ_FLAG_SCROLLABLE);
68	  lv_obj_align(overlay, LV_ALIGN_TOP_LEFT, 0, 0);
69	
70	  /* Flex 布局：垂直居中 */
71	
72	  lv_obj_set_flex_flow(overlay, LV_FLEX_FLOW_COLUMN);
73	  lv_obj_set_flex_align(overlay, LV_FLEX_ALIGN_CENTER,
74	                        LV_FLEX_ALIGN_CENTER,
75	                        LV_FLEX_ALIGN_CENTER);
76	  lv_obj_set_style_pad_row(overlay, 16, 0);
77	
78	  ctx->popup = overlay;
79	
80	  /* 点击任意位置关闭 */
81	
82	  lv_obj_add_event_cb(overlay, overlay_click_cb, LV_EVENT_CLICKED, ctx);
83	
84	  /* 标题 */
85	
86	  ui_create_label(overlay, title, FONT_LARGE, COLOR_TEXT_WHITE);
87	
88	  /* 内容 */
89	
90	  ui_create_label(overlay, content, FONT_MEDIUM, COLOR_TEXT_GRAY);
91	
92	  /* 确认按钮 */
93	
94	  const char *text = btn_text ? btn_text : "确认";
95	  ui_create_button(overlay, 200, 44, text, btn_confirm_cb);
96	
97	  return overlay;
98	}
