29	int tool_vibrate_execute(const char *input_json, char *output, size_t output_size)
30	{
31	#ifdef CONFIG_VIBRATOR
32	    int duration_ms = 200;   /* default */
33	    int amplitude   = 128;   /* default mid-strength */
34	
35	    cJSON *root = cJSON_Parse(input_json);
36	    if (root) {
37	        cJSON *d = cJSON_GetObjectItem(root, "duration_ms");
38	        cJSON *a = cJSON_GetObjectItem(root, "amplitude");
39	        if (d && cJSON_IsNumber(d)) duration_ms = (int)d->valuedouble;
40	        if (a && cJSON_IsNumber(a)) amplitude   = (int)a->valuedouble;
41	        cJSON_Delete(root);
42	    }
43	
44	    /* Clamp values */
45	    if (duration_ms < 1)   duration_ms = 1;
46	    if (duration_ms > 5000) duration_ms = 5000;
47	    if (amplitude < 1)     amplitude = 1;
48	    if (amplitude > 255)   amplitude = 255;
49	
50	    int ret = vibrator_play_oneshot((uint32_t)duration_ms, (uint8_t)amplitude);
51	    if (ret < 0) {
52	        snprintf(output, output_size, "{\"error\":\"vibrator_play_oneshot failed: %d\"}", ret);
53	        return ERROR;
54	    }
55	
56	    snprintf(output, output_size,
57	             "{\"ok\":true,\"duration_ms\":%d,\"amplitude\":%d}",
58	             duration_ms, amplitude);
59	    return OK;
60	#else
61	    (void)input_json;
62	    snprintf(output, output_size, "{\"error\":\"vibrator not enabled\"}");
63	    return ERROR;
64	#endif
65	}
