33	/* -- Private Function Prototypes --------------------------------- */
34	
35	static double get_numeric_value(cJSON* item, bool* ok);
36	static int parse_every_schedule(cJSON* root, cron_job_t* job,
37	    char* output, size_t output_size);
38	static int parse_at_schedule(cJSON* root, cron_job_t* job,
39	    char* output, size_t output_size);
