41	/* -- Private Functions ------------------------------------------- */
42	
43	/* Extract a numeric value from a cJSON item that may be either a
44	 * JSON number or a string containing digits. Many LLMs emit numeric
45	 * parameters as quoted strings; this helper tolerates both forms. */
46	static double get_numeric_value(cJSON* item, bool* ok)
47	{
48	    if (!item) {
49	        *ok = false;
50	        return 0.0;
51	    }
52	
53	    if (cJSON_IsNumber(item)) {
54	        *ok = true;
55	        return item->valuedouble;
56	    }
57	
58	    if (cJSON_IsString(item) && item->valuestring) {
59	        char* end;
60	        double v = strtod(item->valuestring, &end);
61	
62	        if (end != item->valuestring && *end == '\0') {
63	            *ok = true;
64	            return v;
65	        }
66	    }
67	
68	    *ok = false;
69	    return 0.0;
70	}
71	
72	static int parse_every_schedule(cJSON* root, cron_job_t* job,
73	    char* output, size_t output_size)
74	{
75	    bool ok;
76	    double val = get_numeric_value(
77	        cJSON_GetObjectItem(root, "interval_s"), &ok);
78	
79	    if (!ok || val <= 0) {
80	        snprintf(output, output_size,
81	            "Error: 'every' requires positive 'interval_s'");
82	        return ERROR;
83	    }
84	
85	    job->kind = CRON_KIND_EVERY;
86	    job->interval_s = (uint32_t)val;
87	    job->delete_after_run = false;
88	    return OK;
89	}
90	
91	static int parse_at_schedule(cJSON* root, cron_job_t* job,
92	    char* output, size_t output_size)
93	{
94	    bool ok;
95	    double val = get_numeric_value(
96	        cJSON_GetObjectItem(root, "at_epoch"), &ok);
97	
98	    if (!ok || val <= 0) {
99	        snprintf(output, output_size,
100	            "Error: 'at' requires 'at_epoch' "
101	            "(unix timestamp as a number)");
102	        return ERROR;
103	    }
104	
105	    job->kind = CRON_KIND_AT;
106	    job->at_epoch = (int64_t)val;
107	
108	    time_t now = time(NULL);
109	
110	    if (job->at_epoch <= now) {
111	        snprintf(output, output_size,
112	            "Error: at_epoch %lld is in the past (now=%lld)",
113	            (long long)job->at_epoch, (long long)now);
114	        return ERROR;
115	    }
116	
117	    cJSON* delete_j = cJSON_GetObjectItem(root, "delete_after_run");
118	    job->delete_after_run = delete_j ? cJSON_IsTrue(delete_j) : true;
119	    return OK;
120	}
