122	/* -- Public Functions -------------------------------------------- */
123	
124	int tool_cron_add_execute(const char* input_json,
125	    char* output, size_t output_size)
126	{
127	    cJSON* root = cJSON_Parse(input_json);
128	
129	    if (!root) {
130	        snprintf(output, output_size, "Error: invalid JSON input");
131	        return ERROR;
132	    }
133	
134	    const char* name = cJSON_GetStringValue(
135	        cJSON_GetObjectItem(root, "name"));
136	    const char* schedule_type = cJSON_GetStringValue(
137	        cJSON_GetObjectItem(root, "schedule_type"));
138	    const char* message = cJSON_GetStringValue(
139	        cJSON_GetObjectItem(root, "message"));
140	
141	    /* Some LLMs use "description" instead of "message" */
142	    if (!message) {
143	        message = cJSON_GetStringValue(
144	            cJSON_GetObjectItem(root, "description"));
145	    }
146	
147	    if (!name || !schedule_type || !message) {
148	        snprintf(output, output_size,
149	            "Error: missing required fields. "
150	            "You MUST provide: name, schedule_type, message. "
151	            "Example: {\"name\":\"meeting_reminder\","
152	            "\"schedule_type\":\"at\","
153	            "\"at_epoch\":1773990900,"
154	            "\"message\":\"该开会了\"}. "
155	            "Call get_current_time first, then compute "
156	            "at_epoch = current_epoch + delay_seconds.");
157	        cJSON_Delete(root);
158	        return ERROR;
159	    }
160	
161	    if (strlen(message) == 0) {
162	        snprintf(output, output_size,
163	            "Error: message must not be empty");
164	        cJSON_Delete(root);
165	        return ERROR;
166	    }
167	
168	    cron_job_t job;
169	    memset(&job, 0, sizeof(job));
170	    strncpy(job.name, name, sizeof(job.name) - 1);
171	    strncpy(job.message, message, sizeof(job.message) - 1);
172	
173	    const char* channel = cJSON_GetStringValue(
174	        cJSON_GetObjectItem(root, "channel"));
175	    const char* chat_id = cJSON_GetStringValue(
176	        cJSON_GetObjectItem(root, "chat_id"));
177	
178	    if (channel) {
179	        strncpy(job.channel, channel, sizeof(job.channel) - 1);
180	    }
181	
182	    if (chat_id) {
183	        strncpy(job.chat_id, chat_id, sizeof(job.chat_id) - 1);
184	    }
185	
186	    const char* action = cJSON_GetStringValue(
187	        cJSON_GetObjectItem(root, "action"));
188	    const char* action_args = cJSON_GetStringValue(
189	        cJSON_GetObjectItem(root, "action_args"));
190	
191	    if (action) {
192	        strncpy(job.action, action, sizeof(job.action) - 1);
193	    }
194	
195	    if (action_args) {
196	        strncpy(job.action_args, action_args, sizeof(job.action_args) - 1);
197	    }
198	
199	    if (strcmp(job.channel, AGENT_CHAN_FEISHU) == 0
200	        && (job.chat_id[0] == '\0'
201	            || strcmp(job.chat_id, "cron") == 0)) {
202	        snprintf(output, output_size,
203	            "Error: channel='feishu' requires a valid chat_id");
204	        cJSON_Delete(root);
205	        return ERROR;
206	    }
207	
208	    int ret;
209	
210	    if (strcmp(schedule_type, "every") == 0) {
211	        ret = parse_every_schedule(root, &job, output, output_size);
212	    } else if (strcmp(schedule_type, "at") == 0) {
213	        ret = parse_at_schedule(root, &job, output, output_size);
214	    } else {
215	        snprintf(output, output_size,
216	            "Error: schedule_type must be 'every' or 'at'");
217	        cJSON_Delete(root);
218	        return ERROR;
219	    }
220	
221	    cJSON_Delete(root);
222	
223	    if (ret != OK) {
224	        return ret;
225	    }
226	
227	    int err = cron_add_job(&job);
228	
229	    if (err != OK) {
230	        snprintf(output, output_size,
231	            "Error: failed to add job (%s)", strerror(errno));
232	        return err;
233	    }
234	
235	    if (job.kind == CRON_KIND_EVERY) {
236	        snprintf(output, output_size,
237	            "OK: Added recurring job '%s' (id=%s), "
238	            "runs every %lu seconds. Next run at epoch %lld.",
239	            job.name, job.id,
240	            (unsigned long)job.interval_s,
241	            (long long)job.next_run);
242	    } else {
243	        snprintf(output, output_size,
244	            "OK: Added one-shot job '%s' (id=%s), "
245	            "fires at epoch %lld.%s",
246	            job.name, job.id,
247	            (long long)job.at_epoch,
248	            job.delete_after_run
249	                ? " Will be deleted after firing."
250	                : "");
251	    }
252	
253	    syslog(LOG_INFO, "[tool_cron] cron_add: %s\n", output);
254	    return OK;
255	}
