257	int tool_cron_list_execute(const char* input_json,
258	    char* output, size_t output_size)
259	{
260	    (void)input_json;
261	
262	    cron_job_t jobs[AGENT_CRON_MAX_JOBS];
263	    int count = cron_list_jobs(jobs, AGENT_CRON_MAX_JOBS);
264	
265	    if (count == 0) {
266	        snprintf(output, output_size, "No cron jobs scheduled.");
267	        return OK;
268	    }
269	
270	    size_t off = 0;
271	
272	    off += snprintf(output + off, output_size - off,
273	        "Scheduled jobs (%d):\n", count);
274	
275	    for (int i = 0; i < count && off < output_size - 1; i++) {
276	        const cron_job_t* j = &jobs[i];
277	
278	        if (j->kind == CRON_KIND_EVERY) {
279	            off += snprintf(output + off, output_size - off,
280	                "  %d. [%s] \"%s\" every %lus, %s, "
281	                "next=%lld, last=%lld, ch=%s:%s\n",
282	                i + 1, j->id, j->name,
283	                (unsigned long)j->interval_s,
284	                j->enabled ? "enabled" : "disabled",
285	                (long long)j->next_run,
286	                (long long)j->last_run,
287	                j->channel, j->chat_id);
288	        } else {
289	            off += snprintf(output + off, output_size - off,
290	                "  %d. [%s] \"%s\" at %lld, %s, "
291	                "last=%lld, ch=%s:%s%s\n",
292	                i + 1, j->id, j->name,
293	                (long long)j->at_epoch,
294	                j->enabled ? "enabled" : "disabled",
295	                (long long)j->last_run,
296	                j->channel, j->chat_id,
297	                j->delete_after_run ? " (auto-delete)" : "");
298	        }
299	    }
300	
301	    syslog(LOG_INFO, "[tool_cron] cron_list: %d jobs\n", count);
