295	static void pipe_connect_cb(euv_pipe_t* handle, int status, void* user_data)
296	{
297	    (void)user_data;
298	
299	    /* Guard: if deinit happened while connect was in-flight, discard */
300	    pthread_mutex_lock(&g_ble_net.lock);
301	    bool still_alive = g_ble_net.initialized;
302	    pthread_mutex_unlock(&g_ble_net.lock);
303	
304	    if (!still_alive) {
305	        syslog(LOG_WARNING, "[%s] Late pipe_connect_cb after deinit, "
306	                            "discarding\n",
307	            TAG);
308	        euv_pipe_disconnect(handle);
309	        return;
310	    }
311	
312	    if (status != 0) {
313	        syslog(LOG_ERR, "[%s] Pipe connect failed: %d\n", TAG, status);
314	        /* euv_pipe_connect allocates the handle before calling this callback.
315	         * On failure we must disconnect to free the pipe object. */
316	        euv_pipe_disconnect(handle);
317	        pthread_mutex_lock(&g_ble_net.lock);
318	        g_ble_net.pipe_handle = NULL;
319	        g_ble_net.pipe_connected = false;
320	        pthread_mutex_unlock(&g_ble_net.lock);
321	        return;
322	    }
323	
324	    syslog(LOG_INFO, "[%s] SPP proxy pipe connected\n", TAG);
325	
326	    /* Start reading from pipe (data from phone) */
327	    int ret = euv_pipe_read_start(handle, READ_BUF_SIZE, pipe_read_cb, NULL);
328	    if (ret != 0) {
329	        syslog(LOG_ERR, "[%s] Pipe read start failed: %d\n", TAG, ret);
330	        euv_pipe_disconnect(handle);
331	        pthread_mutex_lock(&g_ble_net.lock);
332	        g_ble_net.pipe_handle = NULL;
333	        g_ble_net.pipe_connected = false;
334	        pthread_mutex_unlock(&g_ble_net.lock);
335	        return;
336	    }
337	
338	    /* Set both pipe_handle and pipe_connected atomically under lock */
339	    pthread_mutex_lock(&g_ble_net.lock);
340	    g_ble_net.pipe_handle = handle;
341	    g_ble_net.pipe_connected = true;
342	    pthread_mutex_unlock(&g_ble_net.lock);
343	
344	    /* Bring up TUN interface */
345	    tun_set_up(true);
346	}
